const {spawnSync} = require('child_process');
const EXE = '/workspace/dataset/test17_executable';
function run(args){
  const r = spawnSync(EXE, args, {encoding:'buffer', maxBuffer:1<<24});
  return {code:r.status, out:r.stdout.toString('utf8'), err:r.stderr.toString('utf8')};
}
function probe(flag, v){
  const base = {a:'1', b:'1', c:'ab', d:'2', e:'cd', f:'1', g:'2'};
  base[flag] = v;
  const args = [];
  for (const k of ['a','b','c','d','e','f','g']) { args.push('--'+k, base[k]); }
  const r = run(args);
  let kind, detail;
  const m = r.err.match(/bytes object of wrong length, expected (-?\d+), found (\d+)/);
  const ai = r.err.match(/error: argument --[a-g]: invalid int value: (.*)$/m);
  if (m){ kind='PARSED'; detail='val='+m[1]; }
  else if (ai){ kind='INVALID'; detail='repr='+JSON.stringify(ai[1]); }
  else if (r.code===0){ kind='OK'; detail='stdout='+JSON.stringify(r.out); }
  else { kind='OTHER'; detail=r.err.trim().split('\n').filter(x=>!/^\s+File|^Traceback/.test(x)).join(' | '); }
  return {code:r.code, kind, detail, err:r.err, out:r.out};
}
const probeD = (v)=>probe('d', v);
module.exports={run, probe, probeD};

